// resolver.lookup('api.example.com') walks:
//   root ns        -> where is .com?
//   .com TLD ns    -> where is example.com?
//   example.com ns -> what is api.example.com? (the authoritative answer)
// each hop's answer gets cached at the resolver for its own TTL

// A record: api.example.com -> 203.0.113.10, TTL 3600
// During an outage: change the record to the healthy IP
// Reality: some fraction of resolvers keep serving the STALE IP
//          for up to the remaining TTL — this is why 3600s hurts here

// api.example.com    TTL 60    -- can fail over in ~a minute
// static.example.com TTL 86400 -- rarely changes, cache hard
//
// the trade: 60s TTL means ~60x the query volume of a 3600s TTL

// SOA record's minimum field sets the NEGATIVE cache TTL
// example.com. SOA ns1.example.com. admin.example.com. (
//   2024010100 ; serial
//   7200       ; refresh
//   3600       ; retry
//   1209600    ; expire
//   300        ; minimum  <- NXDOMAIN answers cached for 300s
// )

function resolveFor(resolverRegion) {
  const table = { 'us-east': '203.0.113.10', 'eu-west': '198.51.100.20' };
  return table[resolverRegion] ?? table['us-east'];   // default region
}
